create extension if not exists pgcrypto;
create type public.bha_role as enum ('student','parent','teacher','admin');
create type public.exam_kind as enum ('JAMB','WAEC','NECO','BHA');
create type public.attempt_status as enum ('in_progress','submitted','scored');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role public.bha_role not null default 'student', created_at timestamptz not null default now());
create table public.subjects(id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true);
create table public.topics(id uuid primary key default gen_random_uuid(), subject_id uuid not null references public.subjects(id) on delete cascade, name text not null, unique(subject_id,name));
create table public.questions(id uuid primary key default gen_random_uuid(), exam public.exam_kind not null, subject_id uuid not null references public.subjects(id), topic_id uuid references public.topics(id), stem text not null, options jsonb not null check(jsonb_typeof(options)='array'), correct_option text not null, explanation text, difficulty smallint not null default 2 check(difficulty between 1 and 5), source_label text not null default 'BHA Authored', approved boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.exams(id uuid primary key default gen_random_uuid(), title text not null, exam public.exam_kind not null, subject_id uuid references public.subjects(id), duration_minutes integer not null check(duration_minutes>0), question_count integer not null check(question_count>0), published boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.exam_questions(exam_id uuid references public.exams(id) on delete cascade, question_id uuid references public.questions(id) on delete cascade, position integer not null, primary key(exam_id,question_id));
create table public.attempts(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, exam_id uuid not null references public.exams(id), status public.attempt_status not null default 'in_progress', started_at timestamptz not null default now(), submitted_at timestamptz, score numeric(6,2), correct_count integer, total_count integer);
create table public.answers(id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.attempts(id) on delete cascade, question_id uuid not null references public.questions(id), selected_option text, flagged boolean not null default false, saved_at timestamptz not null default now(), unique(attempt_id,question_id));
create table public.parent_students(parent_id uuid not null references public.profiles(id) on delete cascade, student_id uuid not null references public.profiles(id) on delete cascade, primary key(parent_id,student_id));
create table public.ai_insights(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, attempt_id uuid references public.attempts(id) on delete cascade, kind text not null, content text not null, provider text not null, model text not null, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.subjects enable row level security; alter table public.topics enable row level security; alter table public.questions enable row level security; alter table public.exams enable row level security; alter table public.exam_questions enable row level security; alter table public.attempts enable row level security; alter table public.answers enable row level security; alter table public.parent_students enable row level security; alter table public.ai_insights enable row level security;
create function public.my_role() returns public.bha_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create policy "profile_self" on public.profiles for select using(id=auth.uid() or public.my_role() in ('teacher','admin'));
create policy "catalog_authenticated" on public.subjects for select to authenticated using(true); create policy "topics_authenticated" on public.topics for select to authenticated using(true);
create policy "approved_questions" on public.questions for select to authenticated using(approved or public.my_role() in ('teacher','admin'));
create policy "published_exams" on public.exams for select to authenticated using(published or public.my_role() in ('teacher','admin')); create policy "published_exam_questions" on public.exam_questions for select to authenticated using(exists(select 1 from public.exams e where e.id=exam_id and (e.published or public.my_role() in ('teacher','admin'))));
create policy "student_attempts" on public.attempts for select using(student_id=auth.uid() or public.my_role() in ('teacher','admin') or exists(select 1 from public.parent_students ps where ps.parent_id=auth.uid() and ps.student_id=attempts.student_id)); create policy "student_create_attempt" on public.attempts for insert with check(student_id=auth.uid()); create policy "student_update_attempt" on public.attempts for update using(student_id=auth.uid() and status='in_progress');
create policy "student_answers" on public.answers for all using(exists(select 1 from public.attempts a where a.id=attempt_id and a.student_id=auth.uid())) with check(exists(select 1 from public.attempts a where a.id=attempt_id and a.student_id=auth.uid() and a.status='in_progress'));
create policy "parent_links" on public.parent_students for select using(parent_id=auth.uid() or student_id=auth.uid() or public.my_role() in ('teacher','admin'));
create policy "own_ai_insights" on public.ai_insights for select using(student_id=auth.uid() or public.my_role() in ('teacher','admin') or exists(select 1 from public.parent_students ps where ps.parent_id=auth.uid() and ps.student_id=ai_insights.student_id));
create index attempts_student_idx on public.attempts(student_id,started_at desc); create index answers_attempt_idx on public.answers(attempt_id); create index questions_lookup_idx on public.questions(exam,subject_id,topic_id,approved);
insert into public.subjects(name) values ('English'),('Oral English'),('Mathematics'),('Further Mathematics'),('Chemistry'),('Physics'),('Biology'),('Economics'),('Government'),('CRS'),('Literature in English'),('Commerce'),('Accounting'),('Geography'),('Computer Studies') on conflict do nothing;